#!/usr/bin/env python3
"""Render captured, redacted evidence; never contacts Plex."""
import html,json,pathlib
HERE=pathlib.Path(__file__).resolve().parent;E=HERE/'evidence'
d=json.loads((E/'legacy-read-only.json').read_text());version=next(x['pms_version'] for x in d['observations'] if x['name']=='Secure PMS credential comparison')
rows=[('Authentication','JWT works with Plex cloud but receives PMS 401. The separate legacy browser PIN produced an opaque token accepted by this PMS.'),('Browse / search / artwork','Five music libraries; correct bounded five-track pages and offsets; track search results; authenticated JPEG prefix.'),('Playlists','Create, rename, append distinct track, reorder, remove and delete verified on fresh disposable playlists. All fixture playlists were removed.'),('Duplicates','Direct add, repeated-ID create and queue import collapsed playlist duplicates. The temporary source queue itself did preserve duplicate occurrences.'),('Original media','Generic client profile yields a direct-play decision for the sampled stereo FLAC. Start/later bounded Range reads return 206; a fresh connection returned matching bytes.'),('Credentials','Own JWT device retired, issued token rejected, renewal rejected, local item removed. Compatibility credential intentionally retained in its own keyring item.'),('Keyring','Versioned ASCII envelope passed six byte-exact fixtures and restored a key that renewed successfully. Locked private-bus access is rejected; headless unlock remains failed.'),('Still unverified','Shared permission loss, playback reporting, real outage recovery, artwork replacement, actual account-token expiry, broader formats/ordering and gain units/provenance.')]
body=''.join('<tr><th>'+html.escape(k)+'</th><td>'+html.escape(v)+'</td></tr>' for k,v in rows)
links=''.join('<li><a href="'+html.escape(p.name)+'">'+html.escape(p.name)+'</a></li>' for p in sorted(E.glob('*.json')))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Qoda · Live Plex evidence</title><style>body{margin:0;background:#121c16;color:#e7eee8;font:17px/1.65 system-ui}main{max-width:980px;margin:auto;padding:48px 24px}h1{font-size:clamp(32px,5vw,50px);line-height:1.15}.eyebrow,a,th{color:#bedf9a}p{color:#c0cec2;max-width:80ch}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin:30px 0}.card{padding:20px;background:#1d2c21;border-radius:10px}.metric{display:block;font-size:28px;color:#cbe8aa}table{width:100%;border-collapse:collapse}th,td{padding:15px 10px;border-bottom:1px solid #334438;text-align:left;vertical-align:top}th{width:23%}.note{background:#302c1e;border-left:3px solid #d5b66f;padding:18px}h2{margin-top:36px}li{margin:7px 0}pre{white-space:pre-wrap;font-size:14px}</style><main><div class="eyebrow">QODA / LIVE PLEX VALIDATION</div><h1>Connected to Plex.<br>Compatibility limits measured.</h1><p>One authorized owned server, PMS __VERSION__. Bounded disposable-harness observations; the live acceptance task remains open.</p><div class="cards"><div class="card"><b class="metric">200</b>opaque-token PMS access</div><div class="card"><b class="metric">401</b>JWT PMS access</div><div class="card"><b class="metric">5</b>music libraries discovered</div><div class="card"><b class="metric">206</b>original FLAC Range reads</div></div><table>__ROWS__</table><p class="note">A successful direct-play decision and Range support do not verify real-time gapless output, ALSA precision or downstream hardware fidelity.</p><h2>Cleanup boundary</h2><p>All fresh test playlists were deleted and checked as missing. The additional temporary source queue returned 200 on clear, but a follow-up read still showed contents: empty-state cleanup is unverified. No existing queue was cleared. No timeline/scrobble report or audible playback was sent, and no raw music file was saved.</p><h2>Evidence</h2><p>No account/server/library names, identifiers, endpoints, PINs, keys, tokens or raw content are included. Initial failures remain captured.</p><ul>__LINKS__</ul><details><summary>Full scope and reproduction notes</summary><pre>__GUIDE__</pre></details><p><a href="https://github.com/42lizard/qoda-player/issues/16">Open live-validation task</a></p></main></html>'''
for k,v in [('__VERSION__',html.escape(version)),('__ROWS__',body),('__LINKS__',links),('__GUIDE__',html.escape((HERE/'README.md').read_text()))]:page=page.replace(k,v)
(E/'report.html').write_text(page)
